// Grab the output from the Form Trigger (Node 1)
const input = $input.first().json;

// Generate a clean, URL-safe Article ID
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const cleanKeyword = input.seed_keyword.replace(/\s+/g, '-').toLowerCase().slice(0, 30);
const articleId = `${timestamp}-${cleanKeyword}`;

// Construct the centralized Master Object
const master = {
  article_id: articleId,
  seed_keyword: input.seed_keyword,
  llm_provider: input.llm_provider,
  persona_override: input.persona_override || 'default_icp',
  strategic_notes: input.strategic_notes || '',
  pipeline_phase: '0A_intent_classification',
  created_at: new Date().toISOString(),
  intent: null,
  serp_data: null,
  gap_analysis: null,
  selected_subtopics: null,
  angle_options: null,
  selected_angle: null,
  outline_options: null,
  confirmed_outline: null,
  article_context_document: null,
  section_drafts: [],
  full_draft: null,
  errors: []
};

// Return the data wrapped in the master object
return { json: { master } };

// 1. Explicitly grab the master object from Node 2 ("Initialize Master Object")
// This prevents data loss if the file read node dropped the incoming JSON.
const master = $('Initialize Master Object').first().json.master;

// 2. Grab the file content from the current input (Node 3)
let personaText = "Persona context not found.";

// Check if n8n outputted the file text directly into the JSON 'data' field
if ($input.first().json && $input.first().json.data) {
  personaText = $input.first().json.data;
} 
// Fallback: Check if n8n stored it as a Base64 binary object
else if ($input.first().binary && $input.first().binary.data) {
  const base64Data = $input.first().binary.data.data;
  personaText = Buffer.from(base64Data, 'base64').toString('utf8');
}

// 3. Build the System Prompt (Injecting the Persona Text)
const systemPrompt = `You are a search intent classifier for B2B infrastructure and cloud management content.

Your task is to analyze the given seed keyword and determine:
1. The search intent category
2. The most likely search context
3. The pain tension it maps to

CONTEXT — Target Persona:
${personaText}

INTENT CATEGORIES:
- INFORMATIONAL: The searcher wants to understand a concept, solve a problem, or learn how something works. No commercial comparison implied.
- COMMERCIAL_INVESTIGATION: The searcher is evaluating approaches, comparing categories, or researching before a decision.
- NAVIGATIONAL: The searcher is looking for a specific brand, product, or page. (Flag these — they are not targets for this pipeline.)
- TRANSACTIONAL: The searcher is ready to act. (Flag these — not a primary target in Phase 1.)

PAIN TENSIONS (from persona profile):
1. Cost vs. Capability — cloud costs, attribution, optimization
2. Speed vs. Control — self-service, guardrails, governance
3. Firefighting vs. Building — reactive work, toil, automation investment
4. Visibility vs. Complexity — multi-cloud, inventory, compliance tracking
5. Technical Depth vs. Business Translation — presenting to leadership, business cases

Respond ONLY with a JSON object, no additional text:
{
  "seed_keyword": "<the input keyword>",
  "classified_intent": "<INFORMATIONAL | COMMERCIAL_INVESTIGATION | NAVIGATIONAL | TRANSACTIONAL>",
  "intent_confidence": "<HIGH | MEDIUM | LOW>",
  "primary_pain_tension": "<1-5, which tension this most closely maps to>",
  "secondary_pain_tension": "<1-5 or null>",
  "search_context": "<1-2 sentences describing the likely scenario of someone searching this>",
  "suggested_cluster": "<which topic cluster this maps to>",
  "pipeline_recommendation": "<PROCEED | REVIEW>"
}`;

// 4. Build the User Message
const userMessage = `Classify this seed keyword: "${master.seed_keyword}"

Strategic notes from the user: "${master.strategic_notes}"`;

// 5. Output the master object AND the newly constructed prompts
return {
  json: {
    master: master,
    intent_system_prompt: systemPrompt,
    intent_user_message: userMessage
  }
};

// 1. Grab the Master Object from the source node
const master = $('Initialize Master Object').first().json.master;

// 2. Loop through inputs to find the 'content' field
const allInputs = $input.all();
let aiResponseRaw = "";

for (const item of allInputs) {
  // Your diagnostic showed the data is in 'content'
  if (item.json.content) {
    aiResponseRaw = item.json.content;
    break;
  }
  // Fallback for Gemini 'output' field
  if (item.json.output) {
    aiResponseRaw = item.json.output;
    break;
  }
}

// 3. Clean and Parse
if (aiResponseRaw) {
  try {
    // Remove markdown code blocks
    const cleaned = aiResponseRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(cleaned);

    // Update Master Object
    master.intent = parsed;
    master.intent.pipeline_recommendation = (parsed.pipeline_recommendation || parsed.recommendation || "REVIEW").toUpperCase();
    master.pipeline_phase = '0B_serp_analysis';

    // Clear previous errors if fixed
    master.errors = master.errors.filter(e => e.module !== "0A_intent_classification");

  } catch (e) {
    master.errors.push({ module: "0A_intent_classification", error: "JSON Parse Failure", raw: aiResponseRaw });
  }
} else {
  master.errors.push({ module: "0A_intent_classification", error: "Required field 'content' not found in inputs" });
}

return { json: { master } };

// 1. Reach back to get the Master Object
const master = $('Parse AI Intent').first().json.master;

// 2. Grab the data from your SerpAPI node ("Google search")
const serpData = $('Google search').first().json;

// 3. Map the SerpAPI keys to your competitive prompt
// SerpAPI uses 'organic_results' and 'related_questions'
const systemPrompt = `You are a competitive content analyst specializing in B2B infrastructure.
Analyze the provided Google SERP data to identify content gaps and competitor weaknesses.

CURRENT DOMAIN PHASE: Phase 1 (new domain, no authority). 
TARGET CRITERIA:
- Identify "weak" results (forums like Reddit, thin content, outdated guides).
- Look for "Information Gain" opportunities (topics competitors missed).

Respond ONLY with a JSON object:
{
  "keyword_assessment": {
    "estimated_difficulty": "LOW | MEDIUM | HIGH",
    "phase1_viable": true/false
  },
  "competitive_landscape": {
    "weak_pages_in_top5": 0,
    "top_competitors": [
      { "position": 1, "title": "...", "strength": "weak | moderate | strong" }
    ]
  },
  "content_opportunities": {
    "topic_gaps": ["topic 1", "topic 2"],
    "angle_opportunities": ["unique angle 1"]
  },
  "recommendation": "PROCEED_TO_GAP_ANALYSIS | KEYWORD_TOO_COMPETITIVE"
}`;

const userMessage = `Seed keyword: "${master.seed_keyword}"
INTENT CONTEXT: ${master.intent.search_context}

ORGANIC RESULTS:
${JSON.stringify(serpData.organic_results?.slice(0, 10))}

PEOPLE ALSO ASK / QUESTIONS:
${JSON.stringify(serpData.related_questions)}

RELATED SEARCHES:
${JSON.stringify(serpData.related_searches)}`;

// 4. Update the Master Object and output
master.serp_raw = serpData; // Store the raw data for future reference
master.pipeline_phase = '0B_serp_analysis_prompt';

return {
  json: {
    master: master,
    serp_system_prompt: systemPrompt,
    serp_user_message: userMessage
  }
};

// 1. Grab the Master Object from the last stable point (Finalize SERP Data)
// This ensures we keep the 'intent' and 'serp_raw' data already collected.
const master = $('Finalize SERP Data').first().json.master;

// 2. Loop through inputs to find the AI's response
const allInputs = $input.all();
let aiResponseRaw = "";

for (const item of allInputs) {
  if (item.json.content) {
    aiResponseRaw = item.json.content;
    break;
  }
  if (item.json.output) {
    aiResponseRaw = item.json.output;
    break;
  }
}

// 3. Clean and Parse
if (aiResponseRaw) {
  try {
    const cleaned = aiResponseRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(cleaned);

    // UPDATE: Save specifically to serp_data for the IF node to find it
    master.serp_data = parsed;

    // Standardize recommendation for the IF node
    master.serp_data.recommendation = (parsed.recommendation || "REVIEW").toUpperCase();

    // Advance the pipeline phase
    master.pipeline_phase = '1A_gap_analysis';

  } catch (e) {
    master.errors.push({ module: "0B_serp_analysis", error: "JSON Parse Failure", raw: aiResponseRaw });
  }
} else {
  master.errors.push({ module: "0B_serp_analysis", error: "No AI response found" });
}

return { json: { master } };

const master = $('Parse AI Intent1').first().json.master;

// Explicitly grab each document by its node name
const doc3 = $('Read/Write Files from Disk').first().json.data;
const doc4 = $('Read/Write Files from Disk1').first().json.data;
const doc5 = $('Read/Write Files from Disk2').first().json.data;

const knowledgeDocs = `EEAT Standards:\n${doc3}\n\nSEO Strategy:\n${doc4}\n\nDomain Knowledge:\n${doc5}`;

const systemPrompt = `You are a content strategist for a B2B infrastructure company. 
Your task is to identify "Information Gain" opportunities where we can beat the current SERP.

PART 1 — GAP ANALYSIS:
Identify what competitors cover (commodity info) vs what is missing (genuine gaps).

PART 2 — ANGLE DISCOVERY:
Propose 4-6 thesis-driven angles that are differentiated from the SERP and align with our pain tensions.

KNOWLEDGE CONTEXT:
${knowledgeDocs}

Respond ONLY with a JSON object:
{
  "gap_analysis": {
