      { "topic": "...", "gap_type": "MISSING|OUTDATED", "rationale": "..." }
    ]
  },
  "angle_discovery": [
    { "angle_id": "angle_1", "thesis_statement": "...", "pain_tension": "1-5" }
  ]
}`;

const userMessage = `Seed keyword: "${master.seed_keyword}"
SERP Analysis: ${JSON.stringify(master.serp_data)}
Strategic Notes: "${master.strategic_notes}"`;

return {
  json: {
