  }
};

// 1. Grab the Master Object from the last stable state (Node 17)
const master = $('Code in JavaScript').first().json.master;

// 2. Identify the inputs from the Merge node
const allInputs = $input.all();
let aiResponseRaw = "";

for (const item of allInputs) {
  // Direct check for Ollama (content) and Gemini (output) fields
  if (item.json.content) {
    aiResponseRaw = item.json.content;
    break;
  }
  if (item.json.output) {
    aiResponseRaw = item.json.output;
    break;
  }
}

// 3. Clean and Parse the JSON
if (aiResponseRaw) {
  try {
    // Remove markdown code blocks if the AI added them
    const cleaned = aiResponseRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(cleaned);

    // 4. Update the Master Object with the Gap Analysis findings
    master.gap_analysis = parsed;

    // Move to the next architectural phase: User Selection
    master.pipeline_phase = '1A_user_selection';

    // Clear previous errors for this module
    master.errors = master.errors.filter(e => e.module !== "1A_gap_analysis");

  } catch (e) {
    master.errors.push({
      module: "1A_gap_analysis",
      error: "JSON Parse Failure",
      raw_text_found: aiResponseRaw
    });
  }
} else {
  master.errors.push({
    module: "1A_gap_analysis",
    error: "No AI response content found in Merge Node 2"
  });
}

return { json: { master } };

const master = $json.master;
const gaps = master.gap_analysis.gap_analysis?.content_gaps || master.gap_analysis.content_gaps || [];
const angles = master.gap_analysis.angle_discovery || [];

// Format gaps as a numbered list for display
const gapDisplayText = gaps.map((g, i) => {
  const gapType = g.gap_type || 'GAP';
  const topic = g.topic || 'Unknown topic';
  const rationale = g.rationale || '';
  return `${i + 1}. [${gapType}] ${topic}\n   → ${rationale}`;
}).join('\n\n');

// Format angles as a numbered list for display
const angleDisplayText = angles.map((a, i) => {
  const thesis = a.thesis_statement || a.thesis || 'No thesis';
  const tension = a.pain_tension_alignment || a.pain_tension || 'N/A';
  const angleId = a.angle_id || `angle_${i + 1}`;
  return `${i + 1}. [${angleId}] "${thesis}"\n   Pain Tension: ${tension}`;
}).join('\n\n');

// Build the full form description text
const formDescription = `
=== CONTENT GAPS FOUND ===
${gapDisplayText || 'No gaps identified.'}

=== PROPOSED ANGLES ===
${angleDisplayText || 'No angles generated.'}

INSTRUCTIONS:
- For "interesting_gaps": Type the NUMBERS of the gaps you find compelling, separated by commas (e.g., 1, 3, 4)
- For "preferred_direction": Type the NUMBER of your preferred angle (e.g., 2)
`;

return {
  json: {
    master,
    form_description: formDescription,
    gap_count: gaps.length,
    angle_count: angles.length
  }
};

// ============================================================================
// Process User Selections — Code Node
// Converts user's text input (gap numbers, angle number) into structured data
// ============================================================================

// 1. GET MASTER OBJECT
// Reach back to "Build User Selection Form Data" to get the master object
// (This ensures we have the full gap_analysis data, not just the display text)
const master = $('Build User Selection Form Data').first().json.master;

// 2. GET FORM INPUTS
// The Wait node outputs the user's form submissions
const formData = $input.first().json;

// Validate that we have the expected form fields
if (!formData.interesting_gaps || formData.interesting_gaps.trim() === '') {
  master.errors.push({
    module: '1A_user_selection',
    error: 'No gaps selected',
    detail: 'User did not enter gap numbers'
  });
  return { json: { master } };
}

if (!formData.preferred_direction || formData.preferred_direction.trim() === '') {
  master.errors.push({
    module: '1A_user_selection',
    error: 'No angle selected',
    detail: 'User did not enter angle number'
  });
  return { json: { master } };
}

// 3. PARSE GAP SELECTIONS
// User entered comma-separated numbers like "1, 3, 4"
// Convert to 0-indexed array: [0, 2, 3]
const gapSelectionText = formData.interesting_gaps.trim();
const gapIndices = gapSelectionText
  .split(',')
  .map(s => s.trim())
  .filter(s => s.length > 0)
  .map(s => {
    const num = parseInt(s, 10);
    return isNaN(num) ? null : num - 1; // Convert to 0-indexed
  })
  .filter(i => i !== null);

// Get the actual gap objects from master.gap_analysis
// Handle both possible nesting structures
let allGaps = [];
if (master.gap_analysis && master.gap_analysis.gap_analysis && master.gap_analysis.gap_analysis.content_gaps) {
  allGaps = master.gap_analysis.gap_analysis.content_gaps;
} else if (master.gap_analysis && master.gap_analysis.content_gaps) {
  allGaps = master.gap_analysis.content_gaps;
} else {
  allGaps = [];
}

// Map indices to actual gap objects
const selectedGaps = gapIndices
  .filter(i => i >= 0 && i < allGaps.length)
  .map(i => allGaps[i]);

// Validate that at least one gap was successfully selected
if (selectedGaps.length === 0 && gapIndices.length > 0) {
  // User entered numbers but they don't map to valid gaps
  master.errors.push({
    module: '1A_user_selection',
    error: 'Invalid gap selections',
    detail: `User entered: ${gapSelectionText}. Valid range: 1-${allGaps.length}`,
    user_input: gapSelectionText,
    valid_count: allGaps.length
  });
  return { json: { master } };
}

if (selectedGaps.length === 0) {
  master.errors.push({
    module: '1A_user_selection',
    error: 'No gaps selected',
    detail: 'No valid gaps were selected'
  });
  return { json: { master } };
}

// 4. PARSE ANGLE SELECTION
// User entered a single number like "2"
// Convert to 0-indexed: 1
const angleSelectionText = formData.preferred_direction.trim();
const angleIndex = parseInt(angleSelectionText, 10) - 1; // Convert to 0-indexed

// Get the actual angle objects from master.gap_analysis
let allAngles = [];
if (master.gap_analysis && master.gap_analysis.angle_discovery) {
  allAngles = master.gap_analysis.angle_discovery;
} else {
  allAngles = [];
}

// Get the selected angle object
const selectedAngle = (angleIndex >= 0 && angleIndex < allAngles.length)
  ? allAngles[angleIndex]
  : null;

// Validate angle selection
if (!selectedAngle) {
  const validRange = allAngles.length > 0 ? `1-${allAngles.length}` : 'none available';
  master.errors.push({
    module: '1A_user_selection',
    error: 'Invalid angle selection',
    detail: `User entered: ${angleSelectionText}. Valid range: ${validRange}`,
    user_input: angleSelectionText,
    valid_count: allAngles.length
  });
  return { json: { master } };
}

// 5. UPDATE MASTER OBJECT
// Store selected gaps and angle
master.selected_subtopics = selectedGaps;
master.preferred_direction = selectedAngle;
master.direction_notes = formData.direction_notes || '';

// Update pipeline phase
master.pipeline_phase = '1B_angle_generation';

// Log successful selection to master for auditing
master.selection_summary = {
  gaps_selected: selectedGaps.length,
  gap_topics: selectedGaps.map(g => g.topic || 'Unknown'),
  angle_selected: selectedAngle.thesis_statement || selectedAngle.angle_id || 'Unknown',
  direction_notes: master.direction_notes,
  timestamp: new Date().toISOString()
};

// 6. RETURN UPDATED MASTER
return {
  json: {
    master,
    selection_status: 'SUCCESS',
    summary: master.selection_summary
  }
};

