// 1. VERIFY THIS NAME matches the node immediately BEFORE your Wait node
const buildNodeName = 'Build Outline Selection Form Data'; 

// 2. Safely grab the Master Object
let master;
try {
    master = $(buildNodeName).first().json.master;
} catch (e) {
    throw new Error(`The node "${buildNodeName}" was not found. Please check your canvas and ensure the node name matches exactly (including spaces).`);
}

// 3. Get the user's form submission from the Wait node
const formData = $input.first().json;

// 4. Map the selection (A, B, C) back to the full outline object
const chosenVariant = (formData.selected_outline || "").toUpperCase();
const winningOutline = (master.outline_options || []).find(o => o.variant === chosenVariant);

if (winningOutline) {
    master.confirmed_outline = winningOutline;
    master.outline_modifications = formData.outline_modifications || "";
    master.pipeline_phase = 'brief_scope_generation';
} else {
    master.errors.push({ 
      module: "1B_outline_confirm", 
      error: "Invalid Selection", 
      detail: `User entered "${formData.selected_outline}", but only A, B, or C are valid.` 
    });
}

return { json: { master } };

const master = $json.master;
const outlines = master.outline_options || [];

const outlineDisplayText = outlines.map(o => {
